import java.util.Iterator;
import java.util.NoSuchElementException;

class DataAccessException extends RuntimeException {
    DataAccessException(String message) {
        super(message);
    }
}

class DuplicatedKeyException extends DataAccessException {
    DuplicatedKeyException(String message) {
        super(message);
    }
}

class KeyNotFoundException extends DataAccessException {
    KeyNotFoundException(String message) {
        super(message);
    }
}

class SimpleArrayList<E> implements Iterable<E> {
    private Object[] elements = new Object[8];
    private int size = 0;

    void add(E element) {
        if (size == elements.length) {
            elements = java.util.Arrays.copyOf(elements, elements.length * 2);
        }
        elements[size++] = element;
    }

    @SuppressWarnings("unchecked")
    E get(int index) {
        checkIndex(index);
        return (E) elements[index];
    }

    @SuppressWarnings("unchecked")
    E remove(int index) {
        checkIndex(index);
        E removed = (E) elements[index];
        int numMoved = size - index - 1;
        if (numMoved > 0) {
            System.arraycopy(elements, index + 1, elements, index, numMoved);
        }
        elements[--size] = null;
        return removed;
    }

    int size() {
        return size;
    }

    private void checkIndex(int index) {
        if (index < 0 || index >= size) {
            throw new IndexOutOfBoundsException("index=" + index + ", size=" + size);
        }
    }

    @Override
    public Iterator<E> iterator() {
        return new Iterator<E>() {
            private int cursor = 0;

            @Override
            public boolean hasNext() {
                return cursor < size;
            }

            @Override
            public E next() {
                if (!hasNext()) {
                    throw new NoSuchElementException();
                }
                return get(cursor++);
            }
        };
    }
}

class SimpleHashMap<K, V> {
    private static class Node<K, V> {
        final K key;
        V value;
        Node<K, V> next;

        Node(K key, V value, Node<K, V> next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }
    }

    private Node<K, V>[] buckets;
    private int size = 0;

    @SuppressWarnings("unchecked")
    SimpleHashMap() {
        buckets = new Node[16];
    }

    void put(K key, V value) {
        int index = indexOf(key);
        for (Node<K, V> node = buckets[index]; node != null; node = node.next) {
            if (node.key.equals(key)) {
                throw new DuplicatedKeyException("Key already exists: " + key);
            }
        }
        buckets[index] = new Node<>(key, value, buckets[index]);
        size++;
    }

    V get(K key) {
        int index = indexOf(key);
        for (Node<K, V> node = buckets[index]; node != null; node = node.next) {
            if (node.key.equals(key)) {
                return node.value;
            }
        }
        throw new KeyNotFoundException("Key not found: " + key);
    }

    int size() {
        return size;
    }

    private int indexOf(K key) {
        return Math.floorMod(key.hashCode(), buckets.length);
    }
}

